INSERT INTO products (id, name, sku, category, base_cost, current_price, min_price, max_price, description) VALUES (1, 'AuraPulse Pro ANC Headphones', 'AUR-ANC-01', 'Audio & Acoustics', 120.0, 249.99, 189.99, 299.99, 'High-fidelity wireless headphones with 45dB hybrid active noise cancellation, 40hr battery, and spatial audio.');
